     function createElement(tag, options = {}) {
       const element = document.createElement(tag);
       const { className, text, html, attributes = {}, children = [] } = options;

       if (className) {
         element.className = className;
       }

       if (text !== undefined) {
         element.textContent = text;
       }

       if (html !== undefined) {
         element.innerHTML = html;
       }

       Object.entries(attributes).forEach(([name, value]) => {
         if (value !== undefined && value !== null) {
           element.setAttribute(name, value);
         }
       });

       children.forEach((child) => {
         if (child) {
           element.appendChild(child);
         }
       });

       return element;
     }

     function CheckboxOption({ groupName, optionText, index }) {
       const optionId = groupName + "-" + index;
       const input = createElement("input", {
         attributes: {
           id: optionId,
           type: "checkbox",
           name: groupName,
           value: optionText
         }
       });

       const labelText = createElement("span", {
         className: "choice-label",
         text: optionText
       });

       return createElement("label", {
         className: "choice",
         attributes: { for: optionId },
         children: [input, labelText]
       });
     }

     function QuestionField({ id, name, legend, helpText, options }) {
       const describedBy = helpText ? id + "-help" : undefined;
       const fieldset = createElement("fieldset", {
         attributes: describedBy ? { "aria-describedby": describedBy } : {}
       });

       const legendNode = createElement("legend");
       legendNode.append(
         document.createTextNode(legend + " "),
         createElement("span", { className: "legend-note", text: "(Select all that apply)" })
       );
       fieldset.appendChild(legendNode);

       if (helpText) {
         fieldset.appendChild(
           createElement("p", {
             className: "help-text",
             text: helpText,
             attributes: { id: describedBy }
           })
         );
       }

       fieldset.appendChild(
         createElement("div", {
           className: "choices",
           children: options.map((optionText, index) =>
             CheckboxOption({ groupName: name, optionText, index })
           )
         })
       );

       return createElement("div", {
         className: "form-field",
         children: [fieldset]
       });
     }

     function QuizForm() {
       const form = createElement("form", { attributes: { novalidate: "" } });
       const status = createElement("p", {
         className: "status-message",
         attributes: {
           id: "quiz-status",
           "aria-live": "polite"
         }
       });

       quizQuestions.forEach((question) => {
         form.appendChild(QuestionField(question));
       });

       const submitButton = createElement("button", {
         text: "Submit quiz",
         attributes: { type: "submit" }
       });

       form.appendChild(
         createElement("div", {
           className: "actions",
           children: [submitButton, status]
         })
       );

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const formData = new FormData(form);
         const answeredCount = quizQuestions.filter((question) => {
           return formData.getAll(question.name).length > 0;
         }).length;

         status.textContent = "Quiz submitted. You answered " + answeredCount + " of " + quizQuestions.length + " questions.";
       });

       return form;
     }

     function App() {
       const main = createElement("main", {
         className: "page-shell",
         attributes: { id: "main-content", tabindex: "-1" }
       });

       const card = createElement("section", {
         className: "quiz-card",
         children: [
           createElement("p", { className: "eyebrow", text: "Interactive quiz" }),
           createElement("h1", { text: "Computer Languages Quiz" }),
           createElement("p", {
             className: "intro",
             text: "Explore a short multi-select quiz about programming languages. Each question allows more than one answer, so choose every option you think fits."
           }),
           QuizForm()
         ]
       });

       main.appendChild(card);
       return main;
     }

     document.getElementById("app").appendChild(App());
